 59090  static JSValue js_atomics_op(JSContext *ctx,
 59091                               JSValueConst this_obj,
 59092                               int argc, JSValueConst *argv, int op)
 59093  {
 59094      int size_log2;
 59095      uint64_t v, a, rep_val, idx;
 59096      void *ptr;
 59097      JSValue ret;
 59098      JSClassID class_id;
 59099      JSObject *p;
 59100
 59101      if (js_atomics_get_ptr(ctx, &ptr, &p, &idx, &size_log2, &class_id,
 59102                             argv[0], argv[1], 0))
 59103          return JS_EXCEPTION;
 59104      rep_val = 0;
 59105      if (op == ATOMICS_OP_LOAD) {
 59106          v = 0;
 59107      } else {
 59108          if (size_log2 == 3) {
 59109              int64_t v64;
 59110              if (JS_ToBigInt64(ctx, &v64, argv[2]))
 59111                  return JS_EXCEPTION;
 59112              v = v64;
 59113              if (op == ATOMICS_OP_COMPARE_EXCHANGE) {
 59114                  if (JS_ToBigInt64(ctx, &v64, argv[3]))
 59115                      return JS_EXCEPTION;
 59116                  rep_val = v64;
 59117              }
 59118          } else {
 59119                  uint32_t v32;
 59120                  if (JS_ToUint32(ctx, &v32, argv[2]))
 59121                      return JS_EXCEPTION;
 59122                  v = v32;
 59123                  if (op == ATOMICS_OP_COMPARE_EXCHANGE) {
 59124                      if (JS_ToUint32(ctx, &v32, argv[3]))
 59125                          return JS_EXCEPTION;
 59126                      rep_val = v32;
 59127                  }
 59128          }
 59129          if (typed_array_is_oob(p))
 59130              return JS_ThrowTypeErrorDetachedArrayBuffer(ctx);
 59131          if (idx >= p->u.array.count)
 59132              return JS_ThrowRangeError(ctx, "out-of-bound access");
 59133     }
 59134
 59135     switch(op | (size_log2 << 3)) {
 59136
 59137  #define OP(op_name, func_name)                          \
 59138      case ATOMICS_OP_ ## op_name | (0 << 3):             \
 59139         a = func_name((_Atomic(uint8_t) *)ptr, v);       \
 59140         break;                                           \
 59141      case ATOMICS_OP_ ## op_name | (1 << 3):             \
 59142          a = func_name((_Atomic(uint16_t) *)ptr, v);     \
 59143          break;                                          \
 59144      case ATOMICS_OP_ ## op_name | (2 << 3):             \
 59145          a = func_name((_Atomic(uint32_t) *)ptr, v);     \
 59146          break;                                          \
 59147      case ATOMICS_OP_ ## op_name | (3 << 3):             \
 59148          a = func_name((_Atomic(uint64_t) *)ptr, v);     \
 59149          break;
 59150
 59151          OP(ADD, atomic_fetch_add)
 59152          OP(AND, atomic_fetch_and)
 59153          OP(OR, atomic_fetch_or)
 59154          OP(SUB, atomic_fetch_sub)
 59155          OP(XOR, atomic_fetch_xor)
 59156          OP(EXCHANGE, atomic_exchange)
 59157  #undef OP
 59158
 59159      case ATOMICS_OP_LOAD | (0 << 3):
 59160          a = atomic_load((_Atomic(uint8_t) *)ptr);
 59161          break;
 59162      case ATOMICS_OP_LOAD | (1 << 3):
 59163          a = atomic_load((_Atomic(uint16_t) *)ptr);
 59164          break;
 59165      case ATOMICS_OP_LOAD | (2 << 3):
 59166          a = atomic_load((_Atomic(uint32_t) *)ptr);
 59167          break;
 59168      case ATOMICS_OP_LOAD | (3 << 3):
 59169          a = atomic_load((_Atomic(uint64_t) *)ptr);
 59170          break;
 59171
 59172      case ATOMICS_OP_COMPARE_EXCHANGE | (0 << 3):
 59173          {
 59174              uint8_t v1 = v;
 59175              atomic_compare_exchange_strong((_Atomic(uint8_t) *)ptr, &v1, rep_val);
 59176              a = v1;
 59177          }
 59178          break;
 59179      case ATOMICS_OP_COMPARE_EXCHANGE | (1 << 3):
 59180          {
 59181              uint16_t v1 = v;
 59182              atomic_compare_exchange_strong((_Atomic(uint16_t) *)ptr, &v1, rep_val);
 59183              a = v1;
 59184          }
 59185          break;
 59186      case ATOMICS_OP_COMPARE_EXCHANGE | (2 << 3):
 59187          {
 59188              uint32_t v1 = v;
 59189              atomic_compare_exchange_strong((_Atomic(uint32_t) *)ptr, &v1, rep_val);
 59190              a = v1;
 59191          }
 59192          break;
 59193      case ATOMICS_OP_COMPARE_EXCHANGE | (3 << 3):
 59194          {
 59195              uint64_t v1 = v;
 59196              atomic_compare_exchange_strong((_Atomic(uint64_t) *)ptr, &v1, rep_val);
 59197              a = v1;
 59198          }
 59199          break;
 59200      default:
 59201          abort();
 59202      }
 59203
 59204      switch(class_id) {
 59205      case JS_CLASS_INT8_ARRAY:
 59206          a = (int8_t)a;
 59207          goto done;
 59208      case JS_CLASS_UINT8_ARRAY:
 59209          a = (uint8_t)a;
 59210          goto done;
 59211      case JS_CLASS_INT16_ARRAY:
 59212          a = (int16_t)a;
 59213          goto done;
 59214      case JS_CLASS_UINT16_ARRAY:
 59215          a = (uint16_t)a;
 59216          goto done;
 59217      case JS_CLASS_INT32_ARRAY:
 59218      done:
 59219          ret = JS_NewInt32(ctx, a);
 59220          break;
 59221      case JS_CLASS_UINT32_ARRAY:
 59222          ret = JS_NewUint32(ctx, a);
 59223          break;
 59224      case JS_CLASS_BIG_INT64_ARRAY:
 59225          ret = JS_NewBigInt64(ctx, a);
 59226          break;
 59227      case JS_CLASS_BIG_UINT64_ARRAY:
 59228          ret = JS_NewBigUint64(ctx, a);
 59229          break;
 59230      default:
 59231          abort();
 59232      }
 59233      return ret;
 59234  }
